ht: 400;\\n    text-decoration: none;\\n    cursor: pointer; \\/* Assuming clickable, original was auto or specific for a *\\/\\n    vertical-align: middle; \\/* Ensures alignment if heights vary slightly *\\/\\n}\\n\\n\\/* Specific styles for li.first and li.last *\\/\\n.paginator li.first,\\n.paginator li.last {\\n    border: 0px none rgb(117, 117, 117);\\n    background-color: rgba(0, 0, 0, 0);\\n    color: rgb(117, 117, 117);\\n    width: 28.0903px; \\/* Specific width *\\/\\n    height: 30px; \\/* Specific height *\\/\\n    cursor: auto; \\/* For the <span> or if not a link *\\/\\n}\\n.paginator li.last a {\\n    text-decoration: none;\\n    color: rgb(117, 117, 117);\\n}\\n\\n\\n\\/* Specific styles for li.selected *\\/\\n.paginator li.selected {\\n    border: 0px none rgb(109, 106, 106); \\/* Original was `0px none rgb(109, 106, 106)` and `1.11111px solid rgb(216, 51, 28)` *\\/\\n    background-color: rgba(0, 0, 0, 0);\\n    color: rgb(109, 106, 106);\\n    width: 24.1493px;\\n    height: 31.1111px;\\n}\\n\\n\\/* Specific styles for the number list items (e.g., \'2\', \'3\') *\\/\\n.paginator li:not(.first):not(.last):not(.selected):not(.stick) {\\n    border: 1.11111px solid rgb(216, 51, 28);\\n    background-color: rgba(0, 0, 0, 0);\\n    color: rgb(117, 117, 117);\\n    height: 31.1111px;\\n    \\/* Width varies, consider setting a min-width or specific width if desired *\\/\\n}\\n.paginator li:not(.first):not(.last):not(.selected):not(.stick):nth-of-type(4) {\\n    width: 26.8576px; \\/* Width for \'2\' *\\/\\n}\\n.paginator li:not(.first):not(.last):not(.selected):not(.stick):nth-of-type(6) {\\n    width: 27.1528px; \\/* Width for \'3\' *\\/\\n}\\n\\n\\/* Styles for li.stick *\\/\\n.paginator li.stick {\\n    display: none; \\/* These elements were hidden with display: none *\\/\\n    border: 1.11111px solid rgb(216, 51, 28); \\/* Still include the border in case display changes *\\/\\n    color: rgb(117, 117, 117);\\n}\\n\\n\\/* Styles for anchors withi