INSERT INTO `ps_ce_template` VALUES (1,2,'footer-default','page','\n            <img src=\"/modules/creativeelements/views/img/placeholder.png\" alt=\"\" />We are a team of designers and developers that create high quality Magento, Prestashop, Opencart.        \n            <img src=\"/modules/creativeelements/views/img/placeholder.png\" alt=\"\" /><p>NEED HELP?</p><a href=\"tel:8002034520678208002012320456\">(+800) 345 678, (+800) 123 456</a>        \n			<ul>\n								<li>\n						<a href=\"#\" target=\"_blank\" title=\"facebook\" rel=\"noreferrer noopener\"></a>\n					</li>\n									<li>\n						<a href=\"#\" target=\"_blank\" title=\"twitter\" rel=\"noreferrer noopener\"></a>\n					</li>\n									<li>\n						<a href=\"#\" target=\"_blank\" title=\"instagram\" rel=\"noreferrer noopener\"></a>\n					</li>\n									<li>\n						<a href=\"#\" target=\"_blank\" title=\"youtube\" rel=\"noreferrer noopener\"></a>\n					</li>\n									<li>\n						<a href=\"#\" target=\"_blank\" title=\"whatsapp\" rel=\"noreferrer noopener\"></a>\n					</li>\n									<li>\n						<a href=\"#\" target=\"_blank\" title=\"pinterest\" rel=\"noreferrer noopener\"></a>\n					</li>\n							</ul>\n            <h4>Newsletter</h4><p>Sign up for our e-mail to get latest news.</p>        \n            <a href=\"#\"><img src=\"/modules/creativeelements/views/img/placeholder.png\" alt=\"\" /></a><p></p><p></p>        \n            <a href=\"#\"><img src=\"/modules/creativeelements/views/img/placeholder.png\" alt=\"\" /></a><p></p><p></p>        \n        <p>Copyright © Posthemes. All Rights Reserved.</p>        \n            <img src=\"/modules/creativeelements/views/img/placeholder.png\" alt=\"\" /><p></p><p></p>        \n        ',0,1,'2025-10-28 15:01:21','2025-10-28 15:01:21'),(2,2,'header-default','page','<p>Welcome you to Ecolife store!</p>        \n			<a href=\"http://localhost:8080/moje-konto\">\n									Zaloguj się\n							</a>\n				<a href=\"http://localhost:8080/\">\n					<img src=\"/img/l